prompt --application/shared_components/logic/application_processes/get_oci_speech_token
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(147582746396344917)
,p_process_sequence=>1
,p_process_point=>'ON_DEMAND'
,p_process_name=>'GET_OCI_SPEECH_TOKEN'
,p_static_id=>'get-oci-speech-token'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_response json_object_t;',
'    l_payload  clob;',
'begin',
'    apex_web_service.g_request_headers(1).name  := ''Content-Type'';',
'    apex_web_service.g_request_headers(1).value := ''application/json'';',
'',
'    l_payload := apex_web_service.make_rest_request(',
'        p_url                  => ''https://speech.aiservice.us-ashburn-1.oci.oraclecloud.com/20220101/actions/realtimeSessionToken'',',
'        p_http_method          => ''POST'',',
'        p_body                 => ''{"<Add Compartment OCID Here>"}'',',
'        p_credential_static_id => ''OCI_Creds''',
'    );',
'',
'    if apex_web_service.g_status_code <> 200 then',
'        raise_application_error(',
'            -20001,',
'            ''OCI Speech token request failed. HTTP '' ||',
'            apex_web_service.g_status_code',
'        );',
'    end if;',
'',
'    l_response := json_object_t(l_payload);',
'',
'    apex_json.open_object;',
'    apex_json.write(''token'',         l_response.get_string(''token''));',
'    apex_json.write(''sessionId'',     l_response.get_string(''sessionId''));',
'    apex_json.write(''compartmentId'', l_response.get_string(''compartmentId''));',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
,p_version_scn=>'SH256:unfsU5NrNNXScH1128BRunZ643J8zcWAat6J0bDoK8Q'
,p_created_on=>wwv_flow_imp.dz('20260911130040Z')
,p_updated_on=>wwv_flow_imp.dz('20261014194339Z')
,p_created_by=>'MCA_ADMIN'
,p_updated_by=>'MCA_ADMIN'
);
end;
