prompt --application/shared_components/logic/application_processes/save_speech_segments
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(147582921789346202)
,p_process_sequence=>1
,p_process_point=>'ON_DEMAND'
,p_process_name=>'SAVE_SPEECH_SEGMENTS'
,p_static_id=>'save-speech-segments'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Create an Application Process:',
'--   Name:  SAVE_SPEECH_SEGMENTS',
'--   Point: Ajax Callback: Run this application process when requested by a page process',
'-- Paste the following into its PL/SQL Code attribute.',
'declare',
'    l_recording_id varchar2(64 char);',
'    l_count        pls_integer;',
'    l_segment_no   number;',
'    l_text         varchar2(4000 char);',
'    l_recognized_at varchar2(40 char);',
'begin',
'    apex_json.parse(apex_application.g_x01);',
'',
'    l_recording_id := apex_json.get_varchar2(''recordingId'');',
'    if l_recording_id is null then',
'        raise_application_error(-20001, ''Missing recording ID.'');',
'    end if;',
'',
'    l_count := apex_json.get_count(''segments'');',
'    if l_count is null or l_count = 0 then',
'        raise_application_error(-20002, ''No transcript segments received.'');',
'    end if;',
'',
'    for i in 1 .. l_count loop',
'        l_segment_no := apex_json.get_number(''segments[%d].sequenceNo'', i);',
'        l_text := apex_json.get_varchar2(''segments[%d].transcriptText'', i);',
'        l_recognized_at := apex_json.get_varchar2(''segments[%d].recognizedAt'', i);',
'',
'        if l_segment_no is null or l_text is null then',
'            raise_application_error(-20003, ''Invalid transcript segment.'');',
'        end if;',
'',
'        merge into speech_transcript_segment dst',
'        using (',
'            select l_recording_id as recording_id,',
'                   l_segment_no as segment_no',
'            from dual',
'        ) src',
'        on (    dst.recording_id = src.recording_id',
'            and dst.segment_no   = src.segment_no )',
'        when matched then update set',
'            dst.transcript_text      = l_text,',
'            dst.recognized_at_client = l_recognized_at,',
'            dst.received_at          = systimestamp',
'            where dst.created_by = :APP_USER',
'        when not matched then insert (',
'            recording_id,',
'            segment_no,',
'            transcript_text,',
'            recognized_at_client,',
'            created_by',
'        ) values (',
'            l_recording_id,',
'            l_segment_no,',
'            l_text,',
'            l_recognized_at,',
'            :APP_USER',
'        );',
'    end loop;',
'',
'    commit;',
'',
'    apex_json.open_object;',
'    apex_json.write(''savedSegments'', l_count);',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
,p_version_scn=>'SH256:46mKkPzTZb7E7u1IC6f6NaUTb98HpLUY4U99FpfcrLM'
,p_created_on=>wwv_flow_imp.dz('20260911130053Z')
,p_updated_on=>wwv_flow_imp.dz('20260911130053Z')
,p_created_by=>'MCA_ADMIN'
,p_updated_by=>'MCA_ADMIN'
);
end;
