'declare',
'    l_response json_object_t;',
'    l_payload  clob;',
'begin',
'    apex_web_service.g_request_headers(1).name  := ''Content-Type'';',
'    apex_web_service.g_request_headers(1).value := ''application/json'';',
'',
'    apex_web_service.g_request_headers(2).name  := ''Accept'';',
'    apex_web_service.g_request_headers(2).value := ''application/json'';',
'',
'    l_payload := apex_web_service.make_rest_request(',
'        p_url                  => ''https://speech.aiservice.us-ashburn-1.oci.oraclecloud.com/20220101/actions/realtimeSessionToken'',',
'        p_http_method          => ''POST'',',
'        p_body                 => ''{"compartmentId":"ocid1.compartment.oc1..aaaaaaaacy3hcvugs3y6emokfgmzabe2ju25w7oiszser33w3x3u2ubonjyq"}'',',
'        p_credential_static_id => ''OCI_Creds''',
'    );',
'',
'    :P2_REST_STATUS := ''HTTP '' || apex_web_service.g_status_code;',
'',
'    if apex_web_service.g_status_code <> 200 then',
'        raise_application_error(',
'            -20001,',
'            ''OCI Speech token request failed. HTTP status: '' ||',
'            apex_web_service.g_status_code',
'        );',
'    end if;',
'',
'    l_response := json_object_t(l_payload);',
'',
'    --:P2_SESSION_TOKEN := l_response.get_string(''token'');',
'    --:P2_SESSION       := l_response.get_string(''sessionId'');',
'',
'exception',
'    when others then',
'        :P2_REST_STATUS := ''ERROR: '' || sqlerrm;',
'        raise;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
