wwv_flow_imp_page.create_page(
 p_id=>3
,p_name=>'Documentation'
,p_alias=>'DOCUMENTATION'
,p_page_mode=>'MODAL'
,p_step_title=>'AI Speech - Live Transcription Service Overview'
,p_autocomplete_on_off=>'OFF'
,p_step_template=>2101883943284197310
,p_page_template_options=>'#DEFAULT#'
,p_dialog_height=>'700'
,p_dialog_width=>'1200'
,p_dialog_resizable=>'Y'
,p_protection_level=>'C'
,p_page_component_map=>'11'
,p_created_on=>wwv_flow_imp.dz('20261013142316Z')
,p_last_updated_on=>wwv_flow_imp.dz('20261013142726Z')
,p_created_by=>'MCA_ADMIN'
,p_last_updated_by=>'MCA_ADMIN'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(188119917848742903)
,p_plug_name=>'Documentation'
,p_static_id=>'documentation'
,p_region_template_options=>'#DEFAULT#:t-Region--removeHeader js-removeLandmark:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<section class="oci-live-transcription" aria-labelledby="oci-live-title">',
'  <style>',
'    .oci-live-transcription {',
'      --ink: #24313a;',
'      --muted: #52616b;',
'      --accent: #a94f35;',
'      --line: #dce2e5;',
'      --surface: #f6f8f8;',
'      color: var(--ink);',
'      font: 16px/1.6 system-ui, -apple-system, "Segoe UI", sans-serif;',
'      max-width: 1100px;',
'      margin: 0 auto;',
'    }',
'    .oci-live-transcription * { box-sizing: border-box; }',
'    .oci-live-transcription h1,',
'    .oci-live-transcription h2 { line-height: 1.25; }',
'    .oci-live-transcription h1 { font-size: 2rem; margin: 0 0 .5rem; }',
'    .oci-live-transcription h2 { font-size: 1.35rem; margin: 2rem 0 .7rem; }',
'    .oci-live-transcription p { margin: .6rem 0 1rem; }',
'    .oci-live-transcription a { color: #8d3d28; }',
'    .oci-live-transcription code {',
'      background: #edf1f2;',
'      border-radius: 4px;',
'      padding: .1em .3em;',
'      overflow-wrap: anywhere;',
'    }',
'    .oci-live-transcription .intro {',
'      color: var(--muted);',
'      font-size: 1.08rem;',
'    }',
'    .oci-live-transcription .callout {',
'      background: var(--surface);',
'      border-left: 4px solid var(--accent);',
'      padding: 1rem 1.25rem;',
'      margin: 1.25rem 0;',
'    }',
'    .oci-live-transcription .table-wrap { overflow-x: auto; }',
'    .oci-live-transcription table {',
'      border-collapse: collapse;',
'      width: 100%;',
'      min-width: 680px;',
'      margin: .75rem 0 1.5rem;',
'    }',
'    .oci-live-transcription th,',
'    .oci-live-transcription td {',
'      border-bottom: 1px solid var(--line);',
'      padding: .7rem .8rem;',
'      text-align: left;',
'      vertical-align: top;',
'    }',
'    .oci-live-transcription th {',
'      background: var(--surface);',
'      font-weight: 700;',
'    }',
'    .oci-live-transcription ol,',
'    .oci-live-transcription ul { padding-left: 1.4rem; }',
'    .oci-live-transcription li { margin: .35rem 0; }',
'    .oci-live-transcription .sources {',
'      border-top: 1px solid var(--line);',
'      color: var(--muted);',
'      font-size: .92rem;',
'      padding-top: 1rem;',
'      margin-top: 2rem;',
'    }',
'  </style>',
'',
'  <h1 id="oci-live-title">Oracle AI Speech Live Transcription</h1>',
'  <p class="intro">',
'    Oracle Cloud Infrastructure (OCI) AI Speech Live Transcription converts an',
'    incoming audio stream into text as speech occurs. Applications can use it for',
'    live captions, call assistance, dictation, and other workflows that need',
'    transcription within seconds.',
'  </p>',
'',
'  <div class="callout">',
'    <strong>How the API works:</strong> An OCI REST API operation can create an',
'    authentication token for a live session. The application then connects to',
unistr('    OCI\2019s real-time Speech service over a secure WebSocket, sends audio, and'),
'    receives transcript events. The audio stream itself is not submitted as a',
'    conventional REST transcription job.',
'  </div>',
'',
'  <h2>Typical integration flow</h2>',
'  <ol>',
'    <li>Authorize access to OCI AI Speech through IAM in the intended compartment.</li>',
'    <li>Call <code>CreateRealtimeSessionToken</code> using the Speech REST API or an OCI SDK.</li>',
'    <li>Open a secure WebSocket connection to the real-time Speech endpoint in the same OCI region.</li>',
'    <li>Provide the session authentication and transcription settings, then stream audio in the selected encoding.</li>',
'    <li>Read transcript events, distinguish partial from final text, and display or store the final results.</li>',
'  </ol>',
'',
'  <h2>REST API: session-token attributes</h2>',
'  <p>',
'    The <code>CreateRealtimeSessionToken</code> operation obtains a token for',
'    authenticating a real-time transcription session. Its request body and',
'    response contain these principal attributes:',
'  </p>',
'  <div class="table-wrap">',
'    <table>',
'      <thead>',
'        <tr>',
'          <th scope="col">Attribute</th>',
'          <th scope="col">Direction</th>',
'          <th scope="col">Purpose</th>',
'        </tr>',
'      </thead>',
'      <tbody>',
'        <tr>',
'          <td><code>compartmentId</code></td>',
unistr('          <td>Request \00B7 required</td>'),
'          <td>OCID of the compartment used for authorization.</td>',
'        </tr>',
'        <tr>',
'          <td><code>freeformTags</code></td>',
unistr('          <td>Request \00B7 optional</td>'),
'          <td>Simple key-value tags associated with the session-token resource.</td>',
'        </tr>',
'        <tr>',
'          <td><code>definedTags</code></td>',
unistr('          <td>Request \00B7 optional</td>'),
'          <td>Tags defined within an OCI tag namespace.</td>',
'        </tr>',
'        <tr>',
'          <td><code>token</code></td>',
'          <td>Response</td>',
'          <td>Session JWT used to authenticate with the real-time WebSocket service.</td>',
'        </tr>',
'        <tr>',
'          <td><code>sessionId</code></td>',
'          <td>Response</td>',
'          <td>Identifier of the session associated with the token.</td>',
'        </tr>',
'        <tr>',
'          <td><code>compartmentId</code></td>',
'          <td>Response</td>',
'          <td>Compartment used to create the token.</td>',
'        </tr>',
'      </tbody>',
'    </table>',
'  </div>',
'  <p>',
'    The REST operation also accepts optional <code>opc-request-id</code> for',
'    tracing and <code>opc-retry-token</code> for safe retries. Standard OCI API',
'    request signing and IAM authorization apply to the REST call.',
'  </p>',
'',
'  <h2>Real-time connection attributes</h2>',
'  <p>',
'    The following settings belong to the real-time WebSocket connection. They',
unistr('    are often the most useful \201CAPI attributes\201D when configuring live'),
'    transcription.',
'  </p>',
'  <div class="table-wrap">',
'    <table>',
'      <thead>',
'        <tr>',
'          <th scope="col">Attribute</th>',
'          <th scope="col">What it controls</th>',
'          <th scope="col">Values or notes</th>',
'        </tr>',
'      </thead>',
'      <tbody>',
'        <tr>',
'          <td><code>encoding</code></td>',
'          <td>Format and sample rate of streamed audio.</td>',
'          <td>',
'            Supported examples include <code>audio/raw;rate=16000</code>,',
'            <code>audio/raw;rate=8000</code>, and 8 kHz',
'            <code>mulaw</code> or <code>alaw</code> variants.',
'          </td>',
'        </tr>',
'        <tr>',
'          <td><code>modelType</code></td>',
'          <td>Speech recognition model.</td>',
'          <td><code>ORACLE</code> or <code>WHISPER</code>; Oracle documents <code>ORACLE</code> as the default.</td>',
'        </tr>',
'        <tr>',
'          <td><code>modelDomain</code></td>',
'          <td>Model domain.</td>',
'          <td><code>GENERIC</code> or <code>MEDICAL</code>.</td>',
'        </tr>',
'        <tr>',
'          <td><code>languageCode</code></td>',
'          <td>Language to transcribe.</td>',
'          <td>',
'            Oracle model codes are locale-specific, such as <code>en-US</code>.',
'            Whisper uses language codes such as <code>en</code> and can use',
'            <code>auto</code> for language detection.',
'          </td>',
'        </tr>',
'        <tr>',
'          <td><code>punctuation</code></td>',
'          <td>How punctuation appears in the transcript.</td>',
'          <td>',
'            <code>NONE</code>, <code>AUTO</code>, or <code>SPOKEN</code>.',
'            Spoken punctuation is supported for the Oracle Medical model.',
'          </td>',
'        </tr>',
'        <tr>',
'          <td><code>isAckEnabled</code></td>',
'          <td>Whether the service sends audio acknowledgments.</td>',
'          <td>Boolean; useful when the client needs confirmation that audio packets were received.</td>',
'        </tr>',
'        <tr>',
'          <td><code>partialSilenceThresholdInMs</code></td>',
'          <td>Silence threshold for partial results.</td>',
'          <td>Milliseconds; Oracle model only.</td>',
'        </tr>',
'        <tr>',
'          <td><code>finalSilenceThresholdInMs</code></td>',
'          <td>Silence threshold for final results.</td>',
'          <td>Milliseconds; Oracle model only.</td>',
'        </tr>',
'        <tr>',
'          <td><code>stabilizePartialResults</code></td>',
'          <td>Confidence needed before newer words appear in partial results.</td>',
'          <td><code>NONE</code>, <code>LOW</code>, <code>MEDIUM</code>, or <code>HIGH</code>; Oracle model only.</td>',
'        </tr>',
'        <tr>',
'          <td><code>customizations</code></td>',
'          <td>Custom speech resources applied to recognition.</td>',
'          <td>Array of customization references; Oracle model only.</td>',
'        </tr>',
'        <tr>',
'          <td><code>shouldIgnoreInvalidCustomizations</code></td>',
'          <td>Behavior when a requested customization cannot be loaded.</td>',
'          <td>',
'            Boolean; Oracle model only. When true, the connection can continue',
'            with valid customizations and the base model.',
'          </td>',
'        </tr>',
'      </tbody>',
'    </table>',
'  </div>',
'',
'  <div class="callout">',
'    <strong>Whisper compatibility:</strong> When <code>modelType</code> is',
'    <code>WHISPER</code>, omit',
'    <code>partialSilenceThresholdInMs</code>,',
'    <code>finalSilenceThresholdInMs</code>,',
'    <code>stabilizePartialResults</code>,',
'    <code>customizations</code>, and',
'    <code>shouldIgnoreInvalidCustomizations</code> from the connection',
'    settings. Oracle documents partial transcript results for the Oracle model',
'    only.',
'  </div>',
'',
'  <h2>Transcript events and results</h2>',
'  <p>',
'    The WebSocket service can send <code>CONNECT</code>,',
'    <code>RESULT</code>, <code>ACKAUDIO</code>, and <code>ERROR</code>',
'    events. A <code>RESULT</code> event contains a',
'    <code>transcriptions</code> array. Each transcription includes the',
'    recognized <code>transcription</code> text, an <code>isFinal</code>',
'    flag, <code>startTimeInMs</code> and <code>endTimeInMs</code>',
'    timestamps, a <code>confidence</code> score, and individual',
'    <code>tokens</code>. Tokens can include their own text, type,',
'    timestamps, and confidence score.',
'  </p>',
'  <p>',
'    Treat partial text as provisional in the user interface. Once',
'    <code>isFinal</code> is true, the corresponding result can be committed',
'    to the displayed or stored transcript.',
'  </p>',
'',
'  <h2>Operational notes</h2>',
'  <ul>',
'    <li>Keep the token and OCI credentials out of public application source code.</li>',
unistr('    <li>Match the audio stream\2019s actual encoding and sample rate to the <code>encoding</code> setting.</li>'),
'    <li>Oracle documents a default limit of 10 concurrent live sessions per tenancy; a limit increase can be requested.</li>',
'    <li>For browser applications, Oracle provides a real-time Speech Web SDK.</li>',
'  </ul>',
'',
'  <div class="sources">',
'    <strong>Oracle documentation:</strong>',
unistr('    <a href="https://docs.oracle.com/en-us/iaas/Content/speech/using/using-live-transcribe.htm">Using Live Transcribe</a> \00B7'),
unistr('    <a href="https://docs.oracle.com/en-us/iaas/api/#/en/speech/20220101/RealtimeSessionToken/CreateRealtimeSessionToken">CreateRealtimeSessionToken API</a> \00B7'),
unistr('    <a href="https://docs.oracle.com/en-us/iaas/tools/python/latest/api/ai_speech/models/oci.ai_speech.models.RealtimeParameters.html">RealtimeParameters reference</a> \00B7'),
unistr('    <a href="https://docs.oracle.com/en-us/iaas/releasenotes/speech/aug-25-whisper-new-languages.htm">Whisper live transcription notes</a> \00B7'),
'    <a href="https://docs.oracle.com/en-us/iaas/Content/speech/using/speech.htm">Speech overview and limits</a>',
'  </div>',
'</section>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20261013142345Z')
,p_updated_on=>wwv_flow_imp.dz('20261013142346Z')
,p_created_by=>'MCA_ADMIN'
,p_updated_by=>'MCA_ADMIN'
);
end;
/
